export type CartesianChartData = Extract<ChartData, {
    type: 'line' | 'spline' | 'area' | 'areaspline' | 'column';
}>;

export interface ChartAxisLabelContext extends ContentContext {
    readonly axis: "x" | "y" | "secondaryY";
    readonly index: number;
    readonly tick: Readonly<{
        label: string;
        value?: number | string;
        type?: string;
    }>;
}

export interface ChartContentContextMap {
    title: ChartTitleContext;
    axisLabel: ChartAxisLabelContext;
    dataLabel: ChartDataLabelContext;
    legend: ChartLegendContext;
    tooltip: ChartTooltipContext;
}

export type ChartContentPorts = {
    readonly [K in ChartContentSlotName]?: ChartContentSlot<K>;
} & Readonly<{
    onError?: (diagnostic: ChartDiagnostic) => void;
}>;

export interface ChartContentSlot<K extends ChartContentKey> {
    readonly text: (context: ChartContentFor<K>) => string;
    readonly render?: (host: ChartContentHost<K>, context: ChartRenderContext<K>, signal: AbortSignal) => void | (() => void);
}

export interface ChartDataLabelContext extends ContentContext {
    readonly index: number;
    readonly observation?: PlanObservation;
    readonly annotation?: NonNullable<PlanFrame["annotations"]>[number];
}

export type ChartDiagnostic = Readonly<{
    code: string;
    reason: string;
    path: string;
    message: string;
}>;

export declare enum ChartDownloadFormat {
    Csv = "csv",
    Png = "png",
    Svg = "svg"
}

export declare enum ChartDownloadMenuPosition {
    Top = "top",
    Bottom = "bottom"
}

export interface ChartDrilldownNavigation {
    readonly nodeId: string;
    readonly trail: readonly string[];
}

export type ChartDrilldownNodeData = Extract<ChartData, {
    readonly type: DrilldownType;
}>;

export interface ChartDrilldownOptions {
    readonly chart?: ChartOptions;
    readonly nodes?: Readonly<Record<string, ChartOptions>>;
}

export type ChartLayoutOptions = RootLayout & Partial<Omit<NonNullable<PlanOptions['circular']>, 'gaugeStyle'>> & Readonly<{
    style?: 'solid' | 'needle';
    stackGroups?: PlanOptions['stackGroups'];
    bands?: Extract<PlanSpec, {
        family: 'bullet';
    }>['bands'];
    shape?: Pictorial['shape'];
    gap?: number;
    background?: boolean;
    levels?: Contour['levels'];
    segmentBudget?: number;
}>;

export interface ChartLegendContext extends ContentContext {
    readonly id: string;
    readonly name: string;
    readonly color: string;
    readonly visible: boolean;
}

export interface ChartMountOptions {
    readonly instanceId: string;
    readonly content?: import("./content.js").ChartContentPorts;
    readonly onPointActivate?: (event: Readonly<{
        id: ChartPointId;
        observation: PlanObservation;
        source: "pointer" | "keyboard";
        revision: number;
    }>) => void;
    readonly onHiddenSeriesChange?: (ids: readonly string[]) => void;
    readonly onSelectionChange?: (ids: readonly ChartPointId[]) => void;
    readonly onViewportChange?: (value: PlanViewportValue) => void;
    readonly onDiagnostic?: (diagnostic: ChartDiagnostic) => void;
    readonly synchronization?: import("./synchronization.js").ChartSynchronization;
}

export interface ChartNumberFormat {
    readonly style?: "decimal" | "percent" | "currency" | "unit";
    readonly currency?: string;
    readonly currencyDisplay?: "symbol" | "narrowSymbol" | "code" | "name";
    readonly currencySign?: "standard" | "accounting";
    readonly unit?: string;
    readonly unitDisplay?: "short" | "narrow" | "long";
    readonly prefix?: string;
    readonly suffix?: string;
    readonly notation?: "standard" | "scientific" | "engineering" | "compact";
    readonly minimumFractionDigits?: number;
    readonly maximumFractionDigits?: number;
    readonly useGrouping?: boolean;
    readonly signDisplay?: "auto" | "never" | "always" | "exceptZero";
}

export interface ChartOptions<T extends ChartType = ChartType> {
    readonly title?: string;
    readonly description?: string;
    readonly animation?: Readonly<{
        enabled?: boolean;
        duration?: number;
        revision?: number;
    }>;
    readonly capacity?: PlanOptions["capacity"];
    readonly scales?: PlanOptions["scales"];
    readonly hierarchy?: PlanOptions["hierarchy"];
    readonly referenceBands?: PlanOptions["referenceBands"];
    readonly referenceBandStyles?: readonly ChartReferenceBandStyle[];
    readonly referenceLabels?: readonly Readonly<{
        id: string;
        text: string;
    }>[];
    readonly referenceStyles?: readonly ChartReferenceStyle[];
    readonly annotations?: readonly Readonly<{
        id: string;
        point: ChartPointId;
        text: string;
        dx?: number;
        dy?: number;
    }>[];
    readonly unit?: string;
    readonly theme?: "light" | "dark";
    readonly direction?: "ltr" | "rtl";
    readonly themeTokens?: import("./theme.js").ChartTheme;
    readonly locale?: "en" | "es";
    readonly width?: number;
    readonly height?: number;
    readonly responsive?: readonly ChartResponsiveRule[];
    readonly accessibility?: ChartAccessibilityOptions;
    readonly formatting?: Readonly<{
        locale?: string;
        number?: ChartNumberFormat;
        date?: ChartDateFormat;
    }>;
    readonly layout?: ChartLayoutOptions;
    readonly appearance?: Readonly<{
        colors?: readonly string[];
        series?: readonly ChartSeriesStyle[];
        points?: readonly ChartPointStyle[];
        bandColors?: readonly string[];
        risingColor?: string;
        fallingColor?: string;
        lineWidth?: number;
        markers?: boolean;
        markerRadius?: number;
        dataLabels?: boolean;
        stackLabels?: boolean;
        centerName?: string;
        labelLimit?: number;
        dataLabelLayout?: ChartLabelLayout;
        titleStyle?: ChartTextStyle;
        descriptionStyle?: ChartTextStyle;
        minPlotWidth?: number;
        waterfall?: "waterfall" extends T ? ChartWaterfallStyle : never;
    }>;
    readonly colorAxis?: T extends "heatmap" | "tilemap" ? Extract<PlanSpec, {
        family: "tilemap";
    }>["colorAxis"] : never;
    readonly axes?: Readonly<{
        grid?: boolean;
        x?: ChartAxisOptions;
        y?: ChartAxisOptions;
        secondaryY?: ChartAxisOptions;
    }>;
    readonly legend?: Readonly<{
        visible?: boolean;
        position?: "top" | "bottom" | "left" | "right";
        interactive?: boolean;
        reverse?: boolean;
        maxLabelCharacters?: number;
        itemSpacing?: number;
        maxHeight?: number;
    }>;
    readonly tooltip?: Readonly<{
        enabled?: boolean;
        content?: "point" | "shared";
        placement?: "auto" | "docked" | "below";
        crosshair?: boolean;
        pinnable?: boolean;
        background?: string;
        foreground?: string;
        maxWidth?: number;
        maxHeight?: number;
    }>;
    readonly downloadMenu?: readonly `${ChartDownloadFormat}`[];
    readonly downloadMenuPosition?: `${ChartDownloadMenuPosition}`;
    readonly toolbar?: Readonly<{
        actions: readonly ChartToolbarAction[];
        position?: ChartDownloadMenuPosition;
    }>;
    readonly viewport?: Readonly<{
        axes: "x" | "y" | "xy";
        value?: PlanViewportValue;
        controls?: boolean;
        zoom?: Readonly<ChartZoomOptions>;
        pan?: boolean;
        pinch?: boolean;
        wheel?: false | "ctrl" | "always";
    }>;
    readonly hiddenSeriesIds?: readonly string[];
    readonly selectedPoints?: readonly ChartPointId[];
    readonly references?: PlanOptions["references"];
}

export interface ChartPanel {
    readonly id: string;
    readonly data: ChartData;
}

export interface ChartPanelDiagnostic {
    readonly panelId: string | null;
    readonly diagnostic: ChartDiagnostic;
}

export interface ChartPanelsData {
    readonly panels: readonly ChartPanel[];
    readonly viewportLinks?: readonly ChartPanelViewportLink[];
}

export interface ChartPanelsOptions {
    readonly chart?: ChartOptions;
    readonly panels?: Readonly<Record<string, ChartOptions>>;
    readonly columns?: "auto" | 1 | 2;
}

export interface ChartPanelViewportChange {
    readonly panelId: string;
    readonly value: ChartPanelViewportValue;
    readonly linkId: string | null;
}

export interface ChartPanelViewportLink {
    readonly id: string;
    readonly axis: "x";
    readonly panelIds: readonly string[];
}

export interface ChartPanelVisibilityChange {
    readonly panelId: string;
    readonly hiddenSeriesIds: readonly string[];
}

export type ChartPointId = Readonly<{
    seriesId: string;
    pointId: string;
}>;

export interface ChartPointStyle extends ChartPointId {
    readonly color: string;
}

export interface ChartReferenceBandStyle {
    readonly id: string;
    readonly label?: string;
    readonly color?: string;
    readonly opacity?: number;
}

export interface ChartReferenceStyle {
    readonly id: string;
    readonly color?: string;
    readonly dash?: "solid" | "dashed" | "dotted";
    readonly width?: number;
}

export type ChartRenderContext<K extends ChartContentKey> = ChartContentFor<K> & Readonly<{
    text: string;
}>;

interface ChartTemplateContext<K extends ChartContentKey> {
    readonly $implicit: ChartRenderContext<K>;
    readonly context: ChartRenderContext<K>;
}

export interface ChartTitleContext extends ContentContext {
    readonly description: string;
}

export declare enum ChartDownloadMenuPosition {
    Top = "top",
    Bottom = "bottom"
}

export interface ChartTooltipContext extends ContentContext {
    readonly observation: PlanObservation;
    readonly points: readonly PlanObservation[];
    readonly rows?: readonly ChartTooltipRow[];
    readonly selected: boolean;
}

export interface ChartTooltipRow {
    readonly seriesId: string;
    readonly name: string;
    readonly color: string;
    readonly point: PlanObservation | null;
}

export interface ChartZoomOptions {
    readonly showSlider?: boolean;
    readonly position?: ChartZoomPosition;
    readonly min?: number;
    readonly max?: number;
    readonly step?: number;
    readonly increment?: number;
    readonly label?: string;
}

export declare enum ChartZoomPosition {
    Toolbar = "toolbar",
    Below = "below"
}

